import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"Encryption","description":"","frontmatter":{},"headers":[],"relativePath":"guide/encryption.md","filePath":"guide/encryption.md","lastUpdated":1778915731000}'),n={name:"guide/encryption.md"};function o(r,e,l,p,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h1><p>Pika can encrypt sensitive at-rest data with a server-side master key. The feature is <strong>opt-in</strong>: a fresh install runs without encryption until an administrator enables it from Settings → Server encryption key. Once enabled the key is <strong>never read from disk or environment</strong> — the operator enters it through the web UI (or <code>POST /api/v1/key/unlock</code>) after every restart, and the server runs in a &quot;locked&quot; state until that happens.</p><p>This model mirrors HashiCorp Vault&#39;s seal/unseal pattern, scoped to Pika&#39;s single-key design. The trade-off is a manual unlock step on every restart in exchange for the master key never sitting on disk or in <code>/proc/$pid/environ</code>.</p><h2 id="algorithm" tabindex="-1">Algorithm <a class="header-anchor" href="#algorithm" aria-label="Permalink to &quot;Algorithm&quot;">​</a></h2><ul><li><strong>Cipher</strong>: XChaCha20-Poly1305 (AEAD).</li><li><strong>Key size</strong>: 256 bits (32 bytes).</li><li><strong>Nonce size</strong>: 192 bits (24 bytes).</li><li><strong>KDF</strong>: SHA-256 over the operator-supplied passphrase.</li></ul><p>The passphrase you type is run through SHA-256 to derive the 32-byte cipher key. Any non-empty string works; a long randomly-generated phrase is recommended.</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Pika never persists the encryption key. Lose it and you lose every encrypted record. Store it in a password manager and document its location in your DR plan.</p></div><h2 id="server-lifecycle" tabindex="-1">Server lifecycle <a class="header-anchor" href="#server-lifecycle" aria-label="Permalink to &quot;Server lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────────────────────┐</span></span>
<span class="line"><span>       fresh install│ uninitialized (encryption    │</span></span>
<span class="line"><span>                    │   off — runs as plaintext)   │</span></span>
<span class="line"><span>                    └──────┬───────────────────────┘</span></span>
<span class="line"><span>                           │  Settings → Enable encryption</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>                    ┌──────────────┐</span></span>
<span class="line"><span>                    │   unlocked   │</span></span>
<span class="line"><span>                    └──────┬───────┘</span></span>
<span class="line"><span>                           ▼  restart</span></span>
<span class="line"><span>                    ┌──────────────┐</span></span>
<span class="line"><span>                    │    locked    │  POST /api/v1/key/unlock</span></span>
<span class="line"><span>                    └──────┬───────┘  (verifies key, unlocks)</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>                    ┌──────────────┐</span></span>
<span class="line"><span>                    │   unlocked   │</span></span>
<span class="line"><span>                    └──────────────┘</span></span></code></pre></div><p>A fresh install runs with the encryption layer dormant; the lockgate middleware is a no-op until a verifier exists on disk. The first time an administrator opts in (<code>POST /api/v1/key/initialize</code>, gated by <code>settings.manage</code>) a verifier ciphertext is written into the settings table. From that point on, every restart enters the locked state until an admin authenticates and unlocks. The supplied key is validated against the verifier (AEAD decrypt + magic-prefix check) before the server accepts it; a wrong key is rejected with HTTP 403 without entering the unlocked state.</p><h2 id="wire-format" tabindex="-1">Wire format <a class="header-anchor" href="#wire-format" aria-label="Permalink to &quot;Wire format&quot;">​</a></h2><p>Every encrypted at-rest blob carries a 1-byte format tag followed by the AEAD ciphertext:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[0]      magic byte: 0x01 (single-cipher chacha20-poly1305 envelope)</span></span>
<span class="line"><span>[1..N]   nonce(24) || sealed_payload || tag(16)</span></span></code></pre></div><p>The tag exists so future format upgrades (alternate ciphers, HSM-backed envelopes) can land without breaking on-disk compatibility — <code>internal/secret/envelope</code> dispatches on byte 0.</p><h2 id="what-gets-encrypted" tabindex="-1">What gets encrypted <a class="header-anchor" href="#what-gets-encrypted" aria-label="Permalink to &quot;What gets encrypted&quot;">​</a></h2><p>When the server is unlocked, pika encrypts:</p><ul><li><strong>Mount credentials</strong> stored in settings: S3 secret keys, FTP/SFTP passwords and private keys, WebDAV passwords, Vercel Blob tokens.</li><li><strong>External-resource credentials</strong>: Vault tokens, Vault AppRole secret IDs, AWS secret keys, GCP service-account JSON, Azure client secrets, Kubernetes inline kubeconfig.</li><li><strong>Hook target secrets</strong>: Kafka SASL/SCRAM passwords, Redis passwords, NATS tokens &amp; passwords.</li><li><strong>Server-host private keys</strong>: SFTP host key PEM, FTP TLS key PEM.</li><li><strong>Verifier record</strong>: the 16-byte randomized known-plaintext used to detect a wrong key on unlock.</li></ul><p>User passwords are independently hashed with bcrypt and are not touched by this layer. The personal vault uses end-to-end encryption in the browser; the server-side key has no access to vault contents.</p><p>Operationally-visible fields (mount prefixes, hostnames, port numbers, share names, public access keys) stay plaintext so they remain available in audit logs and during the locked state.</p><h2 id="locked-state-behavior" tabindex="-1">Locked-state behavior <a class="header-anchor" href="#locked-state-behavior" aria-label="Permalink to &quot;Locked-state behavior&quot;">​</a></h2><p>While the server is locked (verifier on disk, no live key):</p><ul><li><code>GET /healthz</code>, <code>GET /api/v1/info</code>, the auth flow (<code>/login/*</code>, <code>/logout</code>, <code>/api/v1/me/*</code>) and the locked-state key endpoints (<code>/api/v1/key/status</code>, <code>/api/v1/key/unlock</code>) keep working.</li><li>Every other request returns <code>503 Service Unavailable</code> with header <code>X-Pika-Locked: true</code> and a JSON body <code>{&quot;code&quot;:&quot;server_locked&quot;,...}</code>.</li><li><code>/api/v1/key/unlock</code> requires both authentication and the <code>settings.manage</code> capability — an unauthenticated probe gets 401, not 503. API automation can call this with a token holding <code>settings.manage</code> (no UI session needed).</li><li>The web UI catches the header and renders a full-screen unlock prompt the moment any background request hits 503.</li><li><code>Settings.Get</code> still returns the row with public fields populated but secret slots blank — the auth bootstrap path can read what it needs without the master key.</li><li><code>Settings.Set</code> fails closed: a write that would persist secret values returns an error rather than storing them in plaintext.</li></ul><h2 id="key-rotation" tabindex="-1">Key rotation <a class="header-anchor" href="#key-rotation" aria-label="Permalink to &quot;Key rotation&quot;">​</a></h2><p><code>POST /api/v1/key/rotate</code> swaps the live key:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cookie: pika_session=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SESSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;current_key&quot;:&quot;old-passphrase&quot;,&quot;new_key&quot;:&quot;new-passphrase&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/key/rotate</span></span></code></pre></div><p>Sequence:</p><ol><li>Validate <code>current_key</code> by AEAD-decrypting the on-disk verifier.</li><li>Read every encrypted-secret blob through the current key into memory.</li><li>Build a new encryptor, re-encrypt the verifier, install the new key as the live encryptor.</li><li>Re-write the secret blobs through the wrapper; they get sealed under the new key on the way out.</li></ol><p>After rotation the next server restart will require the new key. Save it before clicking &quot;Rotate&quot;.</p><p>The legacy <code>POST /api/v1/rotate</code> endpoint and the separate <code>admin_secret</code> settings have been retired — <code>settings.manage</code> is the only auth required to drive any key-lifecycle operation.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p><code>GET /api/v1/backup</code> exports the entire database as a single archive. Backups can themselves be password-protected:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pika-backup.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;http://localhost:8080/api/v1/backup?encryption_password=correct-horse-battery-staple&quot;</span></span></code></pre></div><p>The backup envelope is a separate concern from the at-rest encryption: it covers transport / archival, not on-disk storage. Use both for defence in depth.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The exported backup contains the on-disk ciphertext as-is. To restore, the target server must be unlocked with the SAME key that was active when the backup was taken. Without it the encrypted columns will fail to decrypt after restore.</p></div><h2 id="operational-checklist" tabindex="-1">Operational checklist <a class="header-anchor" href="#operational-checklist" aria-label="Permalink to &quot;Operational checklist&quot;">​</a></h2><ul><li>[ ] On first start, choose a strong server key and store it in a password manager BEFORE clicking Initialize.</li><li>[ ] Document the key&#39;s location and recovery owner in your DR plan — pika cannot recover it for you.</li><li>[ ] Plan for the post-restart unlock step in your operational runbook (Kubernetes rolling restarts, OOM auto-restarts, etc., all require manual unlock now).</li><li>[ ] Take a baseline backup with <code>encryption_password</code> set after configuring secrets.</li><li>[ ] If the host disk is shared (e.g. a Kubernetes PVC on a multi-tenant cluster), at-rest encryption gives you defence in depth even with disk encryption enabled.</li></ul><h2 id="migration-from-pika-secret-encryption-key" tabindex="-1">Migration from <code>PIKA_SECRET_ENCRYPTION_KEY</code> <a class="header-anchor" href="#migration-from-pika-secret-encryption-key" aria-label="Permalink to &quot;Migration from \`PIKA_SECRET_ENCRYPTION_KEY\`&quot;">​</a></h2><p>The <code>PIKA_SECRET_ENCRYPTION_KEY</code> env var (and the equivalent <code>secret.encryption_key</code> config field) is no longer honored. If your deployment sets it:</p><ol><li>Restart pika once to log the deprecation warning and force the manual-unlock flow.</li><li>Sign in to the UI as a superadmin.</li><li>Initialize the server key with the SAME value you previously set in the env var. The verifier gets written; existing encrypted data stays decryptable.</li><li>Remove the env var from your deployment manifest.</li><li>(Optional) Rotate to a new key now that you control the lifecycle interactively.</li></ol><p>If you started a fresh install on the new model and never set the env var, you&#39;ll see the &quot;Set up server encryption key&quot; form on first start.</p>`,40)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
